import{_ as t,H as l,f as o,i as r}from"./chunks/framework.DPC7el8K.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"guide/02-业余无线电考试.md","filePath":"guide/02-业余无线电考试.md","lastUpdated":1780448358000}'),e={name:"guide/02-业余无线电考试.md"};function i(n,a,s,d,h,u){return l(),o("div",null,[...a[0]||(a[0]=[r('<h2 id="📝-业余无线电考试-操作能力验证" tabindex="-1">📝 业余无线电考试（操作能力验证） <a class="header-anchor" href="#📝-业余无线电考试-操作能力验证" aria-label="Permalink to &quot;📝 业余无线电考试（操作能力验证）&quot;">​</a></h2><h3 id="一、设台与使用的基本条件" tabindex="-1">一、设台与使用的基本条件 <a class="header-anchor" href="#一、设台与使用的基本条件" aria-label="Permalink to &quot;一、设台与使用的基本条件&quot;">​</a></h3><p>设置、使用业余无线电台，须<strong>同时满足</strong>以下条件：</p><ol><li>熟悉无线电管理相关法律法规；</li><li>通过操作技术能力验证，<strong>取得对应类别证书</strong>；</li><li>发射设备合规： <ul><li>已取得<strong>型号核准</strong>（含业余频段）；<strong>或</strong></li><li>自制/改装设备（无型号核准，但符合国标、仅限业余频段）。</li></ul></li></ol><blockquote><p>依据：《业余无线电台管理办法》第七条</p></blockquote><h3 id="二、操作证书类别与报考条件" tabindex="-1">二、操作证书类别与报考条件 <a class="header-anchor" href="#二、操作证书类别与报考条件" aria-label="Permalink to &quot;二、操作证书类别与报考条件&quot;">​</a></h3><p>证书分为 <strong>A、B、C 三类</strong>，逐级报考、权限递增。</p><h4 id="🟢-a-类-基础级" tabindex="-1">🟢 A 类（基础级） <a class="header-anchor" href="#🟢-a-类-基础级" aria-label="Permalink to &quot;🟢 A 类（基础级）&quot;">​</a></h4><ul><li>报考条件：熟悉法规，具备<strong>基础操作能力</strong>；</li><li>权限：V/U 频段，适合入门、U/V频段；</li></ul><h4 id="🟡-b-类-进阶级" tabindex="-1">🟡 B 类（进阶级） <a class="header-anchor" href="#🟡-b-类-进阶级" aria-label="Permalink to &quot;🟡 B 类（进阶级）&quot;">​</a></h4><ul><li>报考条件：<strong>持 A 类执照满 6 个月</strong>，有实际通联经验；</li><li>权限：开放HF频段，可在许可的全部业余波段合规通联；</li></ul><h4 id="🔴-c-类-专业级" tabindex="-1">🔴 C 类（专业级） <a class="header-anchor" href="#🔴-c-类-专业级" aria-label="Permalink to &quot;🔴 C 类（专业级）&quot;">​</a></h4><ul><li>报考条件：<strong>持含 30MHz 以下频段执照满 18 个月</strong>；</li><li>权限：可在许可的全部业余波段合规通联、更高功率，适合 DX、实验、竞赛；</li></ul><blockquote><p>依据：《业余无线电台管理办法》第二十五条、第二十六条</p></blockquote><h3 id="三、考试与证书要点" tabindex="-1">三、考试与证书要点 <a class="header-anchor" href="#三、考试与证书要点" aria-label="Permalink to &quot;三、考试与证书要点&quot;">​</a></h3><ul><li>考试由<strong>国家/省级无线电管理机构</strong>组织；</li><li>合格后发放《<strong>业余无线电台操作技术能力验证证书</strong>》；</li><li>证书<strong>全国有效</strong>，是申请电台执照的必要材料；</li><li>禁止<strong>无证发射、超类别操作、跨频段违规使用</strong>。</li></ul>',16)])])}const g=t(e,[["render",i]]);export{_ as __pageData,g as default};
